<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigRegisterdEmailAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigRegisterdEmailAccessor trait.
 *
 * Covers null default, string/VO assignment via withRegisterdEmail,
 * getRegisterdEmail/registerdEmail accessors, and isRegisterdEmailChanged with/without original.
 */
class TenantConfigRegisterdEmailAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRegisterdEmail creates a new instance with the RegisterdEmail set
     * from a string value, and getRegisterdEmail returns the primitive string.
     */
    public function testWithRegisterdEmailFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRegisterdEmailAccessorUnitTest();

        // Act
        $result = $holder->withRegisterdEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getRegisterdEmail());
    }
    /**
     * Asserts that withregisterdEmail has access to the value object
     * from a string value, and getRegisterdEmail returns the primitive string.
     */
    public function testWithRegisterdEmailFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRegisterdEmailAccessorUnitTest();

        // Act
        $result = $holder->withRegisterdEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->registerdEmail()->value());
    }
    public function testChangedRegisterdEmail(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRegisterdEmailAccessorUnitTest();
        $original = $holder->withRegisterdEmail('one');
        $same = $holder->withRegisterdEmail('one');
        $modified = $holder->withRegisterdEmail('other');

        // Act
        $unchanged = $holder->isRegisterdEmailChanged();
        $withSame = $original->isRegisterdEmailChanged($same);
        $withDiferent = $original->isRegisterdEmailChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigRegisterdEmailAccessorUnitTest
{
    use TenantConfigRegisterdEmailAccessor;
}
